export function postBySlug(slug: string) {
  return BLOG_POSTS.find((post) => post.slug === slug);
}

export function filterPosts(category: (typeof BLOG_CATEGORIES)[number], query: string) {
  const words = query.trim().toLocaleLowerCase("ru-RU").split(/\s+/).filter(Boolean);
  return BLOG_POSTS.filter((post) =>
    (category === "Все статьи" || post.category === category) &&
    words.every((word) => `${post.title} ${post.description}`.toLocaleLowerCase("ru-RU").includes(word)),
  );
}

export function relatedPosts(post: BlogPost) {
  return BLOG_POSTS.filter((candidate) => candidate.slug !== post.slug)
    .sort((a, b) => Number(b.category === post.category) - Number(a.category === post.category)).slice(0, 3);
}

export function readingMinutes(post: BlogPost) {
  const text = [...post.intro, ...post.sections.flatMap((section) => [section.title, ...section.paragraphs, ...(section.bullets ?? [])])].join(" ");
  return Math.max(1, Math.ceil(text.split(/\s+/).length / 160));
}

export function formatPostDate(value: string) {
  return new Intl.DateTimeFormat("ru-RU", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${value}T00:00:00Z`));
}